<script setup lang="ts">
import type {Call,ProcessingDetail} from '../../shared/interfaces'
import {analysisLabel,processingLabels,stepLabels,processingReason,providerReason} from '../../shared/lib/processing'
import {datetime} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
defineProps<{call:Call;processing?:ProcessingDetail;timezone?:string;owner?:boolean}>()
</script>
<template><section class="processing-panel" aria-label="Состояние обработки"><div class="section-title"><h3><Icon name="activity" :size="17"/>Обработка разговора</h3><span class="badge" :class="processing?.state==='failed'?'red':'outline'">{{processing?processingLabels[processing.state]:'Состояние обновляется'}}</span></div><div class="processing-stages"><span><Icon :name="call.recording_state==='ready'?'check':'clock'" :size="14"/>1. Запись {{call.recording_state==='ready'?'готова':'ожидается'}}</span><span><Icon :name="call.transcript_state==='ready'?'check':'clock'" :size="14"/>2. {{call.transcript_state==='ready'?'Текст готов':'Расшифровка'}}</span><span><Icon :name="call.analysis_state==='analyzed'?'check':'activity'" :size="14"/>3. {{analysisLabel(call)}}</span></div><template v-if="processing"><p v-if="processing.step" class="subtle">Текущий этап: {{stepLabels[processing.step]}} · попытка {{processing.attempts}} из {{processing.max_attempts}}</p><p v-if="processing.error_code" class="processing-error">{{processingReason(processing.error_code)}}</p><p v-if="processing.next_attempt_at&&processing.state==='retry'" class="subtle">Следующая попытка: {{datetime(processing.next_attempt_at,timezone)}}</p><div v-if="processing.job_id&&['queued','running','retry'].includes(processing.state)" class="queue-summary"><span v-if="processing.queue.ready_ahead!==null">Перед этим заданием: {{processing.queue.ready_ahead}}</span><span>Готовы к запуску: {{processing.queue.ready_total}}</span><span>В работе: {{processing.queue.running_total}}</span><span>Отложены: {{processing.queue.scheduled_total}}</span><small>Очередь только твоей компании. Время ожидания пока неизвестно; состояние обновляется автоматически.</small></div><div v-if="!processing.providers.asr.ready||!processing.providers.analysis.ready" class="processing-blockers"><p v-if="!processing.providers.asr.ready">{{providerReason('asr',processing.providers.asr.reason)}} <RouterLink v-if="owner" class="text-link" to="/settings/asr">Настроить расшифровку →</RouterLink></p><p v-if="!processing.providers.analysis.ready">{{providerReason('analysis',processing.providers.analysis.reason)}} <RouterLink v-if="owner" class="text-link" to="/settings/analysis">Настроить анализ →</RouterLink></p><small>Авторизация Codex в помощнике настраивает чат. Для распознавания аудио нужен отдельный провайдер расшифровки.</small></div></template></section></template>
